/**
 * Bowling type and batting hand for everyone in the archives, not only World Cup players (added
 * 2026-10-30 for the pace/spin split, which needs the type of every bowler a batter faced; the
 * World Cup sheet `players.csv` covered 44% of T20I balls and 42% of league balls).
 *
 * `data/labels/bowler-types.csv` is generated by `npm run data:bowlers` and committed. Fill order
 * for the bowling type, first non-empty wins:
 *   1. data/labels/bowler-entries.csv: reviewed entries with a source link, one row per person
 *   2. players.csv rows entered by hand
 *   3. "mixed" when the snapshot lists both a pace and a spin style: Cricsheet has no type per
 *      ball, so those balls cannot be split and stay out of it unless an entry above settles it
 *   4. the rest of players.csv, then the cricketdata snapshot by Cricsheet id, then by Cricinfo key
 * Matching is by person id throughout, never by name.
 */

import { existsSync, readFileSync, readdirSync } from "node:fs";
import { resolve } from "node:path";
import { bowlGroupOf } from "../analysis/matchups.js";
import { ARCHIVES, LEAGUE_ARCHIVES, archiveIsReady, loadIndex, readMatch, type ArchiveSpec } from "../cricsheet/archive.js";
import { normaliseMatch } from "../cricsheet/match.js";
import { loadPeopleRegister, loadPlayerMeta, normaliseBattingStyle, normaliseBowlingStyle, supplementsReady, type PlayerMeta } from "../cricinfo/player-meta.js";
import { paths, writeText } from "../util/io.js";
import { parseCsvLine, readLabels, toCsv } from "./labels.js";

const COLUMNS = ["personId", "name", "balls", "bowlingType", "handedness", "source", "notes"] as const;
const SHEET_PATH = resolve(paths.labels, "bowler-types.csv");

export interface PersonType {
  bowlingType: string;
  handedness: string;
}

export interface BowlerTypesReport {
  people: number;
  bowlers: number;
  balls: number;
  labelledBalls: number;
  bySource: Record<string, { bowlers: number; balls: number }>;
  unlabelled: { id: string; name: string; balls: number }[];
}

export function readBowlerTypes(): Map<string, PersonType> {
  const out = new Map<string, PersonType>();
  if (!existsSync(SHEET_PATH)) return out;
  const [header, ...lines] = readFileSync(SHEET_PATH, "utf8").split(/\r?\n/).filter(Boolean);
  const cols = parseCsvLine(header ?? "");
  const at = (name: string) => cols.indexOf(name);
  const [id, type, hand] = [at("personId"), at("bowlingType"), at("handedness")];
  for (const line of lines) {
    const cells = parseCsvLine(line);
    out.set(cells[id] ?? "", { bowlingType: cells[type] ?? "", handedness: cells[hand] ?? "" });
  }
  return out;
}

/** Reviewed entries: every `bowler-entries*.csv` in the labels folder, keyed by person id. */
function readEntries(): Map<string, { bowlingType: string; handedness: string; notes: string; file: string }> {
  const out = new Map<string, { bowlingType: string; handedness: string; notes: string; file: string }>();
  for (const file of readdirSync(paths.labels).filter((f) => /^bowler-entries.*\.csv$/.test(f))) {
    const [header, ...lines] = readFileSync(resolve(paths.labels, file), "utf8").split(/\r?\n/).filter(Boolean);
    const cols = parseCsvLine(header ?? "");
    for (const line of lines) {
      const cells = parseCsvLine(line);
      const row = Object.fromEntries(cols.map((c, i) => [c, cells[i] ?? ""]));
      if (row["personId"]) out.set(row["personId"], { bowlingType: row["bowlingType"] ?? "", handedness: row["handedness"] ?? "", notes: [row["notes"], row["sourceUrl"]].filter(Boolean).join(" | "), file });
    }
  }
  return out;
}

/** Everyone who bowled or faced a ball in the archives: id → display name and legal-or-not balls bowled. */
function scanPeople(archives: ArchiveSpec[]): Map<string, { name: string; balls: number }> {
  const people = new Map<string, { name: string; balls: number }>();
  for (const a of archives) {
    if (!archiveIsReady(a)) continue;
    for (const entry of loadIndex(a)) {
      if (entry.gender !== "male") continue;
      const names = new Map(Object.entries(entry.registry).map(([name, id]) => [id, name]));
      const person = (id: string) => people.get(id) ?? people.set(id, { name: names.get(id) ?? id, balls: 0 }).get(id)!;
      for (const inn of normaliseMatch(readMatch(entry.file), entry.id).innings) {
        for (const b of inn.balls) {
          person(b.batter);
          person(b.bowler).balls += 1;
        }
      }
    }
  }
  return people;
}

export function writeBowlerTypes(): BowlerTypesReport {
  const people = scanPeople([ARCHIVES.t20, ARCHIVES.odi, ...LEAGUE_ARCHIVES]);
  const sheet = readLabels();
  const entries = readEntries();
  const meta = supplementsReady() ? loadPlayerMeta() : null;
  const register = supplementsReady() ? loadPeopleRegister() : new Map<string, string[]>();
  const metaOf = (id: string): { m: PlayerMeta; via: string } | null => {
    const direct = meta?.byCricsheetId.get(id);
    if (direct) return { m: direct, via: "snapshot" };
    for (const key of register.get(id) ?? []) {
      const viaKey = meta?.byCricinfoId.get(key);
      if (viaKey) return { m: viaKey, via: "snapshot-register" };
    }
    return null;
  };

  const report: BowlerTypesReport = { people: people.size, bowlers: 0, balls: 0, labelledBalls: 0, bySource: {}, unlabelled: [] };
  const rows = [...people.entries()].sort((a, b) => b[1].balls - a[1].balls || a[0].localeCompare(b[0])).map(([id, p]) => {
    const entry = entries.get(id);
    const row = sheet.get(id);
    const found = metaOf(id);
    const raw = found?.m.bowlingStyle ?? null;
    const code = normaliseBowlingStyle(raw);
    const groups = new Set((raw ?? "").split(",").map((s) => bowlGroupOf(normaliseBowlingStyle(s))).filter(Boolean));
    const handEntered = row?.source === "hand" && row.bowlingType ? row : null;

    let bowlingType = "", source = "";
    if (entry?.bowlingType) { bowlingType = entry.bowlingType; source = `entry:${entry.file}`; }
    else if (handEntered) { bowlingType = handEntered.bowlingType; source = "players-sheet-hand"; }
    else if (groups.size > 1) { bowlingType = "mixed"; source = found!.via; }
    else if (row?.bowlingType) { bowlingType = row.bowlingType; source = "players-sheet"; }
    else if (code) { bowlingType = code; source = found!.via; }

    if (p.balls > 0) {
      report.bowlers += 1;
      report.balls += p.balls;
      if (bowlGroupOf(bowlingType)) report.labelledBalls += p.balls;
      else if (bowlingType !== "mixed" && bowlingType !== "none") report.unlabelled.push({ id, name: p.name, balls: p.balls });
      const s = (report.bySource[source || "unlabelled"] ??= { bowlers: 0, balls: 0 });
      s.bowlers += 1;
      s.balls += p.balls;
    }
    return {
      personId: id, name: p.name, balls: String(p.balls), bowlingType,
      handedness: entry?.handedness || row?.handedness || normaliseBattingStyle(found?.m.battingStyle ?? null),
      source, notes: entry?.notes ?? "",
    };
  });
  writeText(SHEET_PATH, toCsv(COLUMNS, rows));
  return report;
}
